400	    if (current is! ChatReady) {
401	      return;
402	    }
403	    if (_isSending || current.isOffline) {
404	      return;
405	    }
406	    final messages = current.messages;
407	    final aiIndex = messages.indexWhere((message) => message.id == aiMessageId);
408	    // Review finding: defensively checks `role` too, even though only an
409	    // assistant message ever reaches `failed` status today — matches this
410	    // guard clause's own already-defensive shape (`aiIndex == -1`, a
411	    // not-found/structurally-impossible case).
412	    if (aiIndex == -1 ||
413	        messages[aiIndex].role != ChatMessageRole.assistant ||
414	        messages[aiIndex].status != ChatMessageStatus.failed) {
415	      return;
416	    }
417	    ChatUiMessage? userMessage;
418	    for (var i = aiIndex - 1; i >= 0; i--) {
419	      if (messages[i].role == ChatMessageRole.user) {
420	        userMessage = messages[i];
