435	            else
436	              message,
437	        ],
438	        isSending: true,
439	      ),
440	    );
441	
442	    final serverId = userMessage.serverId;
443	    final stream = serverId == null
444	        ? _repository.sendMessage(current.sessionId, userMessage.content)
445	        : _repository.retryMessage(current.sessionId, serverId);
