453	  /// Shared by [sendMessage]/[retryMessage] (Code Map: "extract shared ...
454	  /// helper" extends to this subscribe-and-wait shape too, not just
455	  /// `ChatRemoteDataSource`'s own SSE buffering) — subscribes to [stream],
456	  /// routing every emission through [_applyStreamEvent]/[_markFailed], and
457	  /// resolves once the stream ends (`done`, an in-band error, or a
458	  /// stream-level error), clearing [_isSending]/[ChatReady.isSending]
459	  /// either way via [_finishSending].
460	  Future<void> _consumeStream(
461	    Stream<Either<Failure, ChatStreamEvent>> stream, {
462	    required String userMessageId,
463	    required String aiMessageId,
464	  }) async {
465	    await _sendSubscription?.cancel();
466	    final completer = Completer<void>();
467	    _sendCompleter = completer;
468	    _sendSubscription = stream.listen(
469	      (event) {
470	        event.match(
471	          (failure) => _markFailed(aiMessageId),
472	          (streamEvent) =>
473	              _applyStreamEvent(userMessageId, aiMessageId, streamEvent),
474	        );
475	      },
476	      onError: (Object _, StackTrace _) {
477	        // RNF09: no exception escapes the cubit — a stream-level error
478	        // (shouldn't happen, `ChatRemoteDataSource` never lets one through
479	        // unmapped) still only fails the bubble, never crashes.
480	        _markFailed(aiMessageId);
481	        _finishSending();
482	        if (!completer.isCompleted) {
483	          completer.complete();
484	        }
485	        // Review finding: a stale, already-done subscription reference
486	        // left on `_sendSubscription` made a *later* send/retry's own
487	        // `await _sendSubscription?.cancel()` above hang indefinitely in
488	        // practice (observed via a widget test driving two sends back to
489	        // back) — cleared here (and in the `onDone` branch below)
490	        // exactly where this stream's own lifecycle actually ends,
491	        // rather than relying on cancelling an already-finished
492	        // subscription being an instant no-op.
493	        _sendSubscription = null;
494	        _sendCompleter = null;
495	      },
496	      onDone: () {
497	        _finishSending();
498	        if (!completer.isCompleted) {
499	          completer.complete();
500	        }
501	        _sendSubscription = null;
502	        _sendCompleter = null;
503	      },
504	      cancelOnError: false,
505	    );
506	    await completer.future;
507	  }
